'use strict';
const assert=require('node:assert/strict');
const {moves,policies}=require('./tests/helpers/v0186-catalog.cjs');
const {loadCurrent}=require('./tests/helpers/v0184-engine-harness.cjs');
const {input:base}=require('./tests/fixtures/v0184-public-baseline.json').cases[0];
const move=moves.find(m=>m.id==='gw0170_u056'); assert.ok(move); assert.equal(move.power,90);
const policy=policies[move.id];assert.equal(policy.reason,'パルデアケンタロスのフォルムに応じて技タイプを変更。壁破壊効果は計算対象外');
const context=loadCurrent();
const input={...structuredClone(base),moveId:move.id,moveMechanic:'ragingBull',ragingBullForm:'combat',power:90,moveType:move.type,attTypes:['ノーマル'],defTypes:['ノーマル'],attack:153,defense:117,category:'physical',screen:'none',battleFormat:'doubles'};
const noScreen=Array.from(context.ChlohaDamageEngine.calculate(input).rolls);
const reflectDoubles=Array.from(context.ChlohaDamageEngine.calculate({...input,screen:'reflect'}).rolls);
const lightScreen=Array.from(context.ChlohaDamageEngine.calculate({...input,screen:'lightScreen'}).rolls);
assert.deepEqual(noScreen,[90,90,92,92,94,94,96,96,98,98,100,100,102,102,104,106]);
assert.deepEqual(reflectDoubles,[60,60,61,61,63,63,64,64,65,65,67,67,68,68,69,71]);
assert.deepEqual(reflectDoubles,noScreen.map(d=>Number((BigInt(d)*2732n+2047n)/4096n)));
assert.deepEqual(lightScreen,noScreen);
console.log(JSON.stringify({result:'PASS',policy,noScreen,reflectDoubles,lightScreen,exactInput:input}));
